import api from './master'

export const listPendingReceipts = params => api.get('/v1/erp/inventory/posting/pending-receipts', { params })
export const getPostingReceipt = id => api.get(`/v1/erp/inventory/posting/receipts/${id}`)
export const postPostingReceipt = id => api.post(`/v1/erp/inventory/posting/receipts/${id}/post`)

export const listInventoryBalances = params => api.get('/v1/erp/inventory/balances', { params })
export const getInventoryBalance = id => api.get(`/v1/erp/inventory/balances/${id}`)

export const listInventoryTransactions = params => api.get('/v1/erp/inventory/transactions', { params })
export const getInventoryTransaction = id => api.get(`/v1/erp/inventory/transactions/${id}`)

export const listInventoryAdjustments = params => api.get('/v1/erp/inventory/adjustments', { params })
export const listInventoryAdjustmentReasons = () => api.get('/v1/erp/inventory/adjustments/reasons')
export const saveInventoryAdjustment = data => data.id ? api.put(`/v1/erp/inventory/adjustments/${data.id}`, data) : api.post('/v1/erp/inventory/adjustments', data)
export const submitInventoryAdjustment = id => api.post(`/v1/erp/inventory/adjustments/${id}/submit`)
export const postInventoryAdjustment = id => api.post(`/v1/erp/inventory/adjustments/${id}/post`)
export const cancelInventoryAdjustment = id => api.post(`/v1/erp/inventory/adjustments/${id}/cancel`)
