<template>
  <section class="production-confirm-page">
    <div class="confirm-toolbar">
      <div>
        <div class="crumb">销售订单 / 订单生产确认</div>
        <h1>订单生产确认</h1>
      </div>
      <div>
        <el-button size="small" @click="$router.push('/sales/orders')">返回</el-button>
        <el-button size="small" @click="load">保存检查结果</el-button>
        <el-button size="small" type="success" :disabled="!selected" @click="submit">提交确认</el-button>
      </div>
    </div>

    <el-alert type="info" :closable="false" show-icon title="本页确认库存履约、生产履约、服务履约及资料锁定；不进入生产计划，不创建工单。" />

    <div class="confirm-layout">
      <aside class="order-picker">
        <el-input v-model="query.keyword" size="small" clearable placeholder="搜索销售订单" @keyup.enter.native="loadOrders" />
        <el-table :data="orders" size="mini" border height="620" highlight-current-row @current-change="choose">
          <el-table-column prop="sales_order_no" label="订单号" min-width="145" />
          <el-table-column prop="customer_name" label="客户" min-width="160" show-overflow-tooltip />
          <el-table-column label="状态" width="90"><template slot-scope="{row}"><el-tag size="mini" :type="statusTag(row.production_confirm_status)">{{ statusText(row.production_confirm_status) }}</el-tag></template></el-table-column>
        </el-table>
      </aside>

      <main class="confirm-main">
        <template v-if="selected">
          <div class="order-strip">
            <div><span>销售订单号</span><b>{{ selected.sales_order_no }}</b></div>
            <div><span>客户</span><b>{{ selected.customer_name }}</b></div>
            <div><span>订单日期</span><b>{{ date(selected.order_time) }}</b></div>
            <div><span>交付要求日期</span><b>{{ date(selected.required_delivery_date) }}</b></div>
            <div><span>加急标记</span><el-tag size="mini" :type="selected.is_urgent ? 'danger' : 'info'">{{ selected.is_urgent ? '是' : '否' }}</el-tag></div>
            <div><span>延期标记</span><el-tag size="mini" :type="selected.is_delay ? 'warning' : 'info'">{{ selected.is_delay ? '是' : '否' }}</el-tag></div>
          </div>

          <section class="panel">
            <h3>订单行确认明细</h3>
            <el-table :data="confirmLines" border size="mini">
              <el-table-column label="行号" width="56" align="center"><template slot-scope="{$index}">{{ $index + 1 }}</template></el-table-column>
              <el-table-column prop="product_name" label="产品名称" min-width="150" />
              <el-table-column prop="sku_name" label="SKU名称" min-width="150" />
              <el-table-column label="Item匹配结果" min-width="150"><template slot-scope="{row}">{{ row.item_name || '待系统匹配' }}</template></el-table-column>
              <el-table-column prop="order_qty" label="订单数量" width="86" align="right" />
              <el-table-column prop="inventory_fulfilled_qty" label="库存履约" width="86" align="right" />
              <el-table-column label="生产履约" width="120">
                <template slot-scope="{row}"><el-input-number v-model="row.production_qty" size="mini" :min="0" :max="Number(row.production_required_qty)" :precision="4" controls-position="right" /></template>
              </el-table-column>
              <el-table-column prop="service_fulfilled_qty" label="服务履约" width="86" align="right" />
              <el-table-column label="BOM/工艺/图纸" min-width="210">
                <template slot-scope="{row}">
                  <el-tag v-if="row.production_qty <= 0" size="mini" type="success">无需制造工单</el-tag>
                  <span v-else>
                    <el-tag size="mini" :type="row.bom_snapshot ? 'success' : 'danger'">{{ row.bom_snapshot ? 'BOM已锁定' : '缺BOM' }}</el-tag>
                    <el-tag size="mini" :type="row.routing_snapshot ? 'success' : 'warning'">{{ row.routing_snapshot ? '工艺已锁定' : '待补工艺' }}</el-tag>
                    <el-tag size="mini" :type="row.drawing_snapshot ? 'success' : 'warning'">{{ row.drawing_snapshot ? '图纸已锁定' : '待补图纸' }}</el-tag>
                  </span>
                </template>
              </el-table-column>
              <el-table-column label="操作" width="210" fixed="right">
                <template slot-scope="{row}">
                  <el-button type="text" size="mini" @click="load">重新检查</el-button>
                </template>
              </el-table-column>
              <el-table-column label="确认结果" width="132"><template slot-scope="{row}"><el-tag size="mini" :type="row.production_qty > 0 ? 'success' : 'info'">{{ row.production_qty > 0 ? '生成生产需求契约' : '不进入制造' }}</el-tag></template></el-table-column>
            </el-table>
          </section>

          <section class="panel">
            <h3>生产资料摘要</h3>
            <el-table :data="confirmLines" border size="mini">
              <el-table-column prop="product_name" label="产品名称" min-width="150" />
              <el-table-column label="BOM名称/版本/状态"><template slot-scope="{row}">{{ snapshot(row.bom_snapshot) }}</template></el-table-column>
              <el-table-column label="工艺路线名称/版本/状态"><template slot-scope="{row}">{{ snapshot(row.routing_snapshot) }}</template></el-table-column>
              <el-table-column label="交付检验方案"><template slot-scope="{row}">{{ snapshot(row.inspection_snapshot) }}</template></el-table-column>
              <el-table-column label="图纸状态"><template slot-scope="{row}">{{ snapshot(row.drawing_snapshot) }}</template></el-table-column>
              <el-table-column label="阻塞原因"><template slot-scope="{row}">{{ blockReason(row) }}</template></el-table-column>
              <el-table-column label="补资料" width="118"><template slot-scope="{row}"><el-button v-if="blockReason(row) !== '—'" type="text" size="mini" @click="$router.push(`/sales/orders/${selected.id}/edit`)">返回订单补资料</el-button><span v-else>—</span></template></el-table-column>
            </el-table>
          </section>
        </template>
        <div v-else class="empty-select">请选择待生产确认的销售订单</div>
      </main>

      <aside class="confirm-side" v-if="selected">
        <h3>确认汇总</h3>
        <dl>
          <dt>订单总数量</dt><dd>{{ total('order_qty') }}</dd>
          <dt>库存履约数量</dt><dd>{{ total('inventory_fulfilled_qty') }}</dd>
          <dt>生产履约数量</dt><dd>{{ total('production_qty') }}</dd>
          <dt>服务履约数量</dt><dd>{{ total('service_fulfilled_qty') }}</dd>
          <dt>阻塞行</dt><dd>{{ blockedCount }}</dd>
        </dl>
        <div class="result-box">
          <b>提交结果预览</b>
          <p><i class="el-icon-success" /> 创建生产需求契约 {{ productionRows.length }} 条</p>
          <p><i class="el-icon-success" /> 锁定订单配置快照</p>
          <p><i class="el-icon-success" /> 不生成正式工单</p>
        </div>
        <div class="warn-box">
          服务、安装、辅助录入、无需发货项目不能默认进入制造流程；旧 ERP goods.type=5/6 本轮不新增通用发货表。
        </div>
      </aside>
    </div>
  </section>
</template>

<script>
import { confirmProduction, getProductionPreview, listSalesOrders } from '@/api/erp/sales'
import { statusTag, statusText } from '@/utils/erpStatus'

export default {
  data: () => ({ query: { keyword: '', production_confirm_status: 'pending', page: 1, per_page: 50 }, orders: [], selected: null, confirmLines: [] }),
  computed: {
    productionRows() {
      return this.confirmLines.filter(row => Number(row.production_qty) > 0)
    },
    blockedCount() {
      return this.productionRows.filter(row => this.blockReason(row) !== '—').length
    }
  },
  async created() {
    await this.loadOrders()
    if (this.$route.params.id) {
      const row = this.orders.find(item => String(item.id) === String(this.$route.params.id)) || { id: this.$route.params.id }
      await this.choose(row)
    } else if (this.orders.length) {
      await this.choose(this.orders[0])
    }
  },
  methods: {
    async loadOrders() {
      const { data } = await listSalesOrders(this.query)
      this.orders = data.data || []
    },
    async choose(row) {
      if (!row) return
      const { data } = await getProductionPreview(row.id)
      this.selected = data.order
      this.confirmLines = (this.selected.lines || []).map(line => ({
        ...line,
        production_qty: Number(line.production_required_qty || 0),
        bom_snapshot: line.bom_snapshot || null,
        routing_snapshot: line.routing_snapshot || null,
        inspection_snapshot: line.inspection_snapshot || null,
        drawing_snapshot: line.drawing_snapshot || null
      }))
    },
    async load() {
      if (this.selected) await this.choose(this.selected)
    },
    async submit() {
      if (this.blockedCount > 0) {
        await this.$confirm('当前仍有资料未完全锁定。后端会按真实主数据匹配 BOM，并将工艺路线缺失的生产需求标记为阻塞，不会生成正式工单。继续吗？', '生产确认提示', { type: 'warning' })
      }
      await confirmProduction(this.selected.id, {
        lines: this.productionRows.map(row => ({
          sales_order_line_id: row.id,
          production_qty: row.production_qty
        }))
      })
      this.$message.success('订单生产确认已提交')
      this.$router.push(`/sales/orders/${this.selected.id}/detail`)
    },
    total(field) {
      return this.confirmLines.reduce((sum, row) => sum + Number(row[field] || 0), 0)
    },
    snapshot(v) {
      return v ? `${v.name || v.bom_name || '已锁定'} ${v.version || ''}` : '—'
    },
    statusText,
    statusTag,
    blockReason(row) {
      if (Number(row.production_qty) <= 0) return '—'
      if (!row.bom_snapshot) return '缺少BOM'
      if (row.is_special_customized && !row.drawing_snapshot) return '特殊定制缺图纸'
      return '—'
    },
    date(v) {
      return v ? String(v).replace('T', ' ').slice(0, 10) : '-'
    }
  }
}
</script>

