import { listEntity, saveEntity, disableEntity, enableEntity } from '../../../api/erp/master'
const empty=()=>({id:null,item_code:'',item_name:'',item_type:'raw_material',category_id:null,spec:'',unit_id:null,is_purchase_item:true,is_stock_item:true,is_production_item:false,is_batch_managed:false,is_serial_managed:false,cost_method:'weighted_average',default_supplier_id:null,status:'enabled',remark:''})
export default {name:'ItemList',data(){return{loading:false,saving:false,drawerVisible:false,drawerMode:'detail',rows:[],total:0,categories:[],units:[],suppliers:[],selected:{},form:empty(),query:{keyword:'',item_type:'',category_id:'',status:'',page:1,per_page:20},itemTypes:[{value:'finished_product',label:'成品'},{value:'semi_finished',label:'半成品'},{value:'raw_material',label:'原材料'},{value:'packaging',label:'包装物'},{value:'service',label:'服务'}],rules:{item_code:[{required:true,message:'请输入 Item 编码'}],item_name:[{required:true,message:'请输入物料名称'}],item_type:[{required:true,message:'请选择物料类型'}],unit_id:[{required:true,message:'请选择基本单位'}]}}},computed:{drawerTitle(){return this.drawerMode==='detail'?(this.selected.item_name||'物料详情'):(this.drawerMode==='edit'?'编辑物料':'新增物料')}},created(){this.load();this.loadOptions()},methods:{async load(){this.loading=true;try{const {data}=await listEntity('items',this.query);this.rows=data.data||[];this.total=data.total||0;if(this.selected.id){this.selected=this.rows.find(row=>row.id===this.selected.id)||this.selected}}catch(e){this.$message.error(e.userMessage||'物料数据加载失败')}finally{this.loading=false}},async loadOptions(){const [categories,units,suppliers]=await Promise.all([listEntity('categories',{per_page:100,category_type:'item'}),listEntity('units',{per_page:100}),listEntity('suppliers',{per_page:100})]);this.categories=categories.data.data||[];this.units=units.data.data||[];this.suppliers=suppliers.data.data||[]},reset(){this.query={keyword:'',item_type:'',category_id:'',status:'',page:1,per_page:20};this.load()},openDetail(row){this.selected={...row};this.drawerMode='detail';this.drawerVisible=true},openCreate(){this.form=empty();this.drawerMode='create';this.drawerVisible=true},openEdit(row){this.form={...empty(),...row};this.drawerMode='edit';this.drawerVisible=true},save(){this.$refs.form.validate(async ok=>{if(!ok)return;this.saving=true;try{await saveEntity('items',this.form);this.$message.success('物料保存成功');this.drawerVisible=false;await this.load()}catch(e){this.$message.error(e.userMessage||'物料保存失败')}finally{this.saving=false}})},async toggleStatus(row){const enabling=row.status!=='enabled';try{await this.$confirm(enabling?'确认启用该物料？':'确认停用该物料？',enabling?'启用确认':'停用确认');await(enabling?enableEntity:disableEntity)('items',row.id);await this.load();this.$message.success(enabling?'物料已启用':'物料已停用')}catch(e){if(e!=='cancel')this.$message.error(e.userMessage||'操作失败')}},itemTypeText(v){return(this.itemTypes.find(item=>item.value===v)||{}).label||v||'-'},costMethodText(v){return({weighted_average:'移动加权平均',standard:'标准成本',fifo:'先进先出'})[v]||v||'-'},statusText(v){return v==='disabled'?'停用':'启用'},formatDate(v){return v?String(v).replace('T',' ').slice(0,16):'-'},rowClass({row}){return row.id===this.selected.id?'selected-row':''}}}
