<template>
  <section class="system-frame role-page">
    <div class="system-titlebar">
      <div>
        <div class="system-crumb">系统管理　/　<b>角色权限</b></div>
        <h1>角色权限</h1>
        <p>角色决定菜单、按钮和数据范围；部门负责人可查看本部门数据。</p>
      </div>
      <div class="title-actions">
        <el-button icon="el-icon-question">帮助</el-button>
        <el-button icon="el-icon-refresh" @click="load">刷新</el-button>
      </div>
    </div>

    <div class="role-workbench">
      <aside class="role-list-card">
        <div class="card-head">
          <h2>角色列表</h2>
          <el-button type="success" icon="el-icon-plus" @click="createRole">新增角色</el-button>
        </div>
        <el-input v-model="roleKeyword" clearable placeholder="搜索角色名称或编码" />
        <el-table :data="pagedRoles" height="604" highlight-current-row @row-click="selectRole">
          <el-table-column label="角色编码/名称" min-width="160">
            <template slot-scope="{ row }">
              <strong>{{ row.code }}</strong>
              <small>{{ row.name }}</small>
            </template>
          </el-table-column>
          <el-table-column label="数据范围" width="96"><template slot-scope="{ row }"><el-tag size="mini" :type="scopeType(row.data_scope)">{{ scopeText(row.data_scope) }}</el-tag></template></el-table-column>
          <el-table-column label="成员数" width="66"><template slot-scope="{ row }">{{ roleUserCounts[row.id] || 0 }}</template></el-table-column>
          <el-table-column label="操作" width="54"><template slot-scope="{ row }"><el-button type="text" icon="el-icon-edit" @click.stop="selectRole(row)" /></template></el-table-column>
        </el-table>
        <div class="role-pager">
          <span>共 {{ roleTotal }} 条</span>
          <el-pagination background small layout="prev, pager, next" :page-size.sync="rolePageSize" :current-page.sync="rolePage" :total="roleTotal" @current-change="handleRolePageChange" />
        </div>
      </aside>

      <main class="role-editor" v-if="currentRole">
        <div class="current-role-strip">
          <span><i class="el-icon-success" /> 当前角色：<b>{{ currentRole.name }}</b>（{{ currentRole.code }}）</span>
          <small>创建时间：2026-06-20 10:15:22</small>
          <small>更新时间：2026-07-15 16:48:31</small>
          <el-tag size="mini" type="success">启用</el-tag>
        </div>

        <div class="role-tabs">
          <button :class="{active: activeTab==='menu'}" @click="activeTab='menu'"><i class="el-icon-menu" />菜单权限</button>
          <button :class="{active: activeTab==='button'}" @click="activeTab='button'"><i class="el-icon-mouse" />按钮权限</button>
          <button :class="{active: activeTab==='scope'}" @click="activeTab='scope'"><i class="el-icon-data-analysis" />数据范围</button>
          <button :class="{active: activeTab==='members'}" @click="activeTab='members'"><i class="el-icon-user" />成员({{ roleMembers.length }})</button>
          <button :class="{active: activeTab==='inherit'}" @click="activeTab='inherit'"><i class="el-icon-share" />角色继承</button>
          <button :class="{active: activeTab==='preview'}" @click="activeTab='preview'"><i class="el-icon-document" />权限预览</button>
        </div>

        <section v-show="activeTab==='menu' || activeTab==='button'" class="permission-zone">
          <div class="menu-tree-box">
            <h3>菜单权限 <small>控制菜单可见性</small></h3>
            <el-tree ref="permTree" :data="permissionTree" show-checkbox node-key="id" default-expand-all :props="{ label: 'name', children: 'children' }" @check="syncChecked" />
            <div class="tree-actions">
              <el-button size="mini" @click="expandAll">展开全部</el-button>
              <el-button size="mini" @click="$refs.permTree.setCheckedKeys([])">折叠全部</el-button>
              <el-checkbox v-model="cascade">继承父级菜单</el-checkbox>
            </div>
          </div>

          <div class="button-matrix">
            <h3>按钮权限 <small>控制功能按钮级别权限</small></h3>
            <el-table :data="matrixRows" border height="320">
              <el-table-column prop="module" label="模块" min-width="120" />
              <el-table-column v-for="action in actions" :key="action.key" :label="action.label" width="78" align="center">
                <template slot-scope="{ row }">
                  <el-checkbox v-model="row[action.key]" />
                </template>
              </el-table-column>
              <el-table-column prop="special" label="特殊动作" min-width="130">
                <template slot-scope="{ row }">
                  <el-link v-if="row.special" type="primary">{{ row.special }}</el-link>
                  <span v-else>-</span>
                </template>
              </el-table-column>
            </el-table>
            <div class="matrix-legend">
              <span><i class="el-icon-success" /> 有权限</span>
              <span><i class="el-icon-remove" /> 无权限</span>
              <b><i class="el-icon-warning-outline" /> 删除和审核权限风险较高，请谨慎分配！</b>
              <el-link type="primary">查看权限说明</el-link>
            </div>
          </div>
        </section>

        <section class="lower-zone">
          <div class="scope-card">
            <h3>数据范围 <small>控制可访问的数据范围</small></h3>
            <el-radio-group v-model="currentRole.data_scope">
              <el-radio label="all"><b>全部数据</b><small>可查看和操作所有数据</small></el-radio>
              <el-radio label="department"><b>本部门数据</b><small>仅可查看本部门及子部门数据</small></el-radio>
              <el-radio label="self"><b>本人数据</b><small>仅可查看和操作本人创建的数据</small></el-radio>
            </el-radio-group>
            <el-button size="mini" :disabled="currentRole.data_scope !== 'department'">选择部门</el-button>
          </div>

          <div class="description-card">
            <h3>说明</h3>
            <p>数据范围与菜单、按钮权限共同生效，最终决定用户可见可操作的数据。</p>
            <h4>当前生效范围</h4>
            <div class="scope-preview"><i class="el-icon-info" /> {{ scopePreview }}</div>
            <p class="sample-users">示例用户：张三、李四、王五　等{{ roleUserCounts[currentRole.id] || 0 }}人</p>
          </div>

          <div class="inherit-card">
            <h3>权限继承关系</h3>
            <div class="inherit-node muted">系统管理员（基础角色）</div>
            <i class="el-icon-bottom" />
            <div class="inherit-node active">{{ currentRole.name }}</div>
            <i class="el-icon-bottom" />
            <div class="inherit-node muted">销售人员（继承）</div>
            <el-link type="primary">查看继承关系详情</el-link>
          </div>
        </section>

        <div class="sticky-actions">
          <div class="risk-tip">
            <b>风险提示</b>
            <span>当前角色拥有 {{ checkedPermissionIds.length }} 项权限</span>
          </div>
          <div class="impact">
            <span>权限变更影响</span>
            <b>直接影响用户：{{ roleUserCounts[currentRole.id] || 0 }} 人</b>
            <b>间接影响用户：15 人</b>
          </div>
          <el-button type="success" @click="save">保存权限</el-button>
          <el-button @click="copyRole">复制角色</el-button>
          <el-button>查看影响用户</el-button>
          <el-button type="danger" plain @click="disableRole">禁用角色</el-button>
        </div>
      </main>
    </div>
  </section>
</template>

<script>
import { listPermissions, listRoles, listRoleUsers, saveRole } from '@/api/erp/rbac'

export default {
  data: () => ({
    roles: [],
    permissions: [],
    roleMembers: [],
    roleUserCounts: {},
    currentRole: null,
    checkedPermissionIds: [],
    roleKeyword: '',
    rolePage: 1,
    rolePageSize: 10,
    roleTotal: 0,
    activeTab: 'menu',
    cascade: true,
    actions: [
      { key: 'view', label: '查看' },
      { key: 'create', label: '新增' },
      { key: 'edit', label: '编辑' },
      { key: 'delete', label: '删除' },
      { key: 'audit', label: '审核' },
      { key: 'export', label: '导出' }
    ],
    matrixRows: [
      { module: '销售订单', view: true, create: true, edit: true, delete: true, audit: true, export: true, special: '提交确认、取消' },
      { module: '销售发货', view: true, create: true, edit: true, delete: false, audit: true, export: true, special: '打印发货单' },
      { module: '客户管理', view: true, create: true, edit: true, delete: false, audit: false, export: true, special: '导出客户' },
      { module: '管理员管理', view: true, create: true, edit: true, delete: true, audit: true, export: true, special: '重置密码' },
      { module: '菜单管理', view: true, create: true, edit: true, delete: false, audit: false, export: true, special: '导出菜单' },
      { module: '部门管理', view: true, create: true, edit: true, delete: false, audit: false, export: true, special: '导出部门' }
    ]
  }),
  computed: {
    filteredRoles() {
      return this.roles
    },
    pagedRoles() {
      return this.roles
    },
    permissionTree() {
      const map = {}
      this.permissions.forEach(item => { map[item.id] = { ...item, children: [] } })
      const roots = []
      this.permissions.forEach(item => {
        if (item.parent_id && map[item.parent_id]) map[item.parent_id].children.push(map[item.id])
        else roots.push(map[item.id])
      })
      return roots
    },
    scopePreview() {
      const text = this.scopeText(this.currentRole.data_scope)
      if (this.currentRole.data_scope === 'all') return `可查看：全部业务数据，以及被授权按钮动作。`
      if (this.currentRole.data_scope === 'department') return `可查看：本部门及子部门的销售订单、采购、库存、客户数据。`
      return `可查看：本人创建或归属给本人的销售订单、客户、跟进与业务单据。`
    }
  },
  created() {
    this.load()
  },
  watch: {
    roleKeyword() {
      this.rolePage = 1
      this.load()
    }
  },
  methods: {
    async load() {
      const [{ data: permissions }, { data: roleResponse }] = await Promise.all([
        listPermissions({ tree: 1 }),
        listRoles({ page: this.rolePage, per_page: this.rolePageSize, keyword: this.roleKeyword })
      ])
      this.permissions = permissions
      const roles = roleResponse.data || roleResponse
      this.roles = roles
      this.roleTotal = roleResponse.meta ? roleResponse.meta.total : roles.length
      await this.loadCounts()
      this.selectRole(this.currentRole ? roles.find(item => item.id === this.currentRole.id) || roles[0] : roles[0])
    },
    async loadCounts() {
      const result = {}
      await Promise.all(this.roles.map(async role => {
        try {
          const { data } = await listRoleUsers(role.id, { page: 1, per_page: 1 })
          result[role.id] = data.meta ? data.meta.total : data.length
        } catch (e) {
          result[role.id] = 0
        }
      }))
      this.roleUserCounts = result
    },
    async selectRole(row) {
      if (!row) return
      this.currentRole = { ...row }
      this.checkedPermissionIds = row.permission_ids || []
      this.$nextTick(() => this.$refs.permTree && this.$refs.permTree.setCheckedKeys(this.checkedPermissionIds))
      try {
        const { data } = await listRoleUsers(row.id, { page: 1, per_page: 10 })
        this.roleMembers = data.data || data
      } catch (e) {
        this.roleMembers = []
      }
    },
    handleRolePageChange(page) {
      this.rolePage = page
      this.load()
    },
    syncChecked() {
      this.checkedPermissionIds = this.$refs.permTree ? this.$refs.permTree.getCheckedKeys() : []
    },
    expandAll() {
      this.permissionTree.forEach(node => this.walkTree(node, item => { if (this.$refs.permTree.store.nodesMap[item.id]) this.$refs.permTree.store.nodesMap[item.id].expanded = true }))
    },
    walkTree(node, cb) {
      cb(node)
      ;(node.children || []).forEach(child => this.walkTree(child, cb))
    },
    async save() {
      this.syncChecked()
      await saveRole({ ...this.currentRole, permission_ids: this.checkedPermissionIds })
      this.$message.success('角色权限已保存')
      this.load()
    },
    createRole() {
      this.$message.info('新增角色已预留，确认字段后接入')
    },
    copyRole() {
      this.$message.info('复制角色已预留，复制当前菜单、按钮和数据范围')
    },
    disableRole() {
      this.$message.warning('禁用角色会影响用户权限，请在确认流程中执行')
    },
    scopeText(scope) {
      return ({ all: '全部数据', department: '本部门数据', self: '本人数据' })[scope] || '本人数据'
    },
    scopeType(scope) {
      return ({ all: 'primary', department: 'success', self: 'warning' })[scope] || 'info'
    }
  }
}
</script>

