<template>
  <section class="sir-page" :class="{ 'drawer-open': drawerVisible }">
    <div class="sir-workspace">
      <div class="sir-head">
        <div><h1>SKU 与物料关系</h1><p>销售对象与采购 / 库存 / 生产对象的转换关系</p></div>
        <div><el-button size="small" type="success" icon="el-icon-plus" @click="openCreate">建立关系</el-button><el-button size="small" icon="el-icon-download" @click="$router.push('/master/imports')">批量导入</el-button></div>
      </div>

      <div class="sir-filter">
        <label>SKU编码 / 名称<el-input v-model="filters.sku" size="small" placeholder="请输入编码或名称" clearable /></label>
        <label>Item编码 / 名称<el-input v-model="filters.item" size="small" placeholder="请输入编码或名称" clearable /></label>
        <label>关系角色<el-select v-model="filters.role" size="small" clearable placeholder="全部"><el-option v-for="t in types" :key="t.value" :label="t.label" :value="t.value" /></el-select></label>
        <label>状态<el-select v-model="filters.status" size="small" clearable placeholder="全部"><el-option label="启用" value="enabled" /><el-option label="停用" value="disabled" /></el-select></label>
        <span class="spacer" /><el-button size="small" @click="reset">重置</el-button><el-button size="small" type="success" @click="loadRelations">查询</el-button>
      </div>

      <div class="sir-grid">
        <div class="sku-list-card">
          <h3>SKU 列表 <span>共 {{ filteredSkus.length }} 条</span></h3>
          <el-table :data="filteredSkus" size="mini" border :row-class-name="skuRowClass" @row-click="selectSku">
            <el-table-column width="34"><template slot-scope="{ row }"><el-checkbox :value="selectedSku.id===row.id" /></template></el-table-column>
            <el-table-column prop="sku_code" label="SKU编码" min-width="105" />
            <el-table-column prop="sku_name" label="SKU名称" min-width="120" />
            <el-table-column label="商品" min-width="128"><template slot-scope="{ row }">{{ row.product ? row.product.product_name : '-' }}</template></el-table-column>
            <el-table-column label="销售单位" width="72"><template slot-scope="{ row }">{{ row.product && row.product.unit ? row.product.unit.unit_name : '台' }}</template></el-table-column>
            <el-table-column label="关系数" width="64" align="center"><template slot-scope="{ row }">{{ relationsForSku(row.id).length }}</template></el-table-column>
            <el-table-column label="关系状态" width="78"><template slot-scope="{ row }"><span class="sir-dot" :class="row.status">{{ statusText(row.status) }}</span></template></el-table-column>
          </el-table>
          <div class="pager">共 {{ filteredSkus.length }} 条 <el-pagination small layout="prev, pager, next" :total="filteredSkus.length" :page-size="10" /></div>
        </div>

        <div class="relation-card">
          <div class="sku-title">
            <h2>{{ selectedSku.sku_code || '-' }} <small>{{ selectedSku.sku_name || '' }}</small> <span class="sir-dot">正常</span></h2>
            <p>商品：{{ selectedSku.product ? selectedSku.product.product_name : '-' }}　|　销售单位：{{ selectedSku.product && selectedSku.product.unit ? selectedSku.product.unit.unit_name : '台' }}</p>
            <p>来源系统映射：jt_product_goods_sku.id = {{ selectedSku.id || '-' }}　{{ selectedSku.id ? '已映射' : '-' }}</p>
          </div>
          <div class="flow">
            <div><b>Product</b><span>{{ selectedSku.product ? selectedSku.product.product_name : '-' }}</span></div>
            <i class="el-icon-bottom" />
            <div class="active"><b>SKU</b><span>{{ selectedSku.sku_code || '-' }}<br>{{ selectedSku.sku_name || '-' }}</span></div>
          </div>
          <div class="relation-table-head"><strong>对应物料（{{ currentRelations.length }}）</strong><el-button size="mini" icon="el-icon-plus" @click="openCreate">添加关系</el-button></div>
          <el-table :data="currentRelations" size="mini" border empty-text="暂无对应物料，请添加关系">
            <el-table-column label="角色" min-width="92"><template slot-scope="{ row }">{{ typeText(row.relation_type) }}</template></el-table-column>
            <el-table-column label="物料" min-width="150"><template slot-scope="{ row }"><b>{{ row.item ? row.item.item_code : '-' }}</b><br><small>{{ row.item ? row.item.item_name : '无实体服务项' }}</small></template></el-table-column>
            <el-table-column label="转换数量 / 基准单位" min-width="142"><template slot-scope="{ row }">{{ row.qty }} {{ row.unit ? row.unit.unit_name : '' }}/台</template></el-table-column>
            <el-table-column label="默认" width="64"><template slot-scope="{ row }">{{ row.is_primary ? '是' : '否' }}</template></el-table-column>
            <el-table-column label="生效状态" width="92"><template slot-scope="{ row }"><span class="sir-dot" :class="row.status">{{ row.status==='enabled'?'生效中':'停用' }}</span></template></el-table-column>
            <el-table-column label="操作" width="92"><template slot-scope="{ row }"><el-button type="text" size="mini" @click="openEdit(row)">编辑</el-button><el-button type="text" size="mini" class="danger-link" @click="remove(row)">解除</el-button></template></el-table-column>
          </el-table>
          <div class="sir-warning">提示：关系角色用于销售对象与实体对象转换。生产用料不在这里维护，后续进入 BOM。</div>
        </div>
      </div>
    </div>

    <aside v-if="drawerVisible" class="sir-drawer">
      <div class="drawer-head"><h2>{{ form.id ? '编辑物料关系' : '建立物料关系' }}</h2><i class="el-icon-close" @click="drawerVisible=false" /></div>
      <el-form ref="form" :model="form" :rules="rules" label-position="top" size="small" class="drawer-body">
        <p class="sku-context">SKU：{{ selectedSku.sku_code }}　{{ selectedSku.sku_name }}</p>
        <el-form-item label="选择物料" prop="item_id"><el-select v-model="form.item_id" filterable clearable class="full" placeholder="请选择物料"><el-option v-for="item in items" :key="item.id" :label="`${item.item_code} ${item.item_name}`" :value="item.id" /></el-select></el-form-item>
        <el-form-item label="关系角色" prop="relation_type"><el-select v-model="form.relation_type" class="full"><el-option v-for="t in types" :key="t.value" :label="t.label" :value="t.value" /></el-select></el-form-item>
        <el-form-item label="转换数量" prop="qty"><el-input-number v-model="form.qty" :min="0.0001" :precision="4" controls-position="right" /></el-form-item>
        <el-form-item label="基准单位"><el-select v-model="form.unit_id" clearable class="full"><el-option v-for="unit in units" :key="unit.id" :label="unit.unit_name" :value="unit.id" /></el-select></el-form-item>
        <el-form-item label="是否默认"><el-switch v-model="form.is_primary" active-color="#07883f" /><small>作为该 SKU 的默认物料关系；同角色仅可有一个默认。</small></el-form-item>
        <el-form-item label="状态"><el-radio-group v-model="form.status"><el-radio label="enabled">启用</el-radio><el-radio label="disabled">停用</el-radio></el-radio-group></el-form-item>
        <div class="rule-warning"><b>校验提示</b><p>只有套装、组合销售、固定随货配件，才需要一个 SKU 关联多个 Item。生产用料请在 BOM 中维护，不要在这里维护。</p></div>
        <el-form-item label="备注"><el-input v-model="form.remark" type="textarea" :rows="3" maxlength="100" show-word-limit /></el-form-item>
      </el-form>
      <div class="drawer-footer"><el-button size="small" @click="drawerVisible=false">取消</el-button><el-button size="small" type="success" :loading="saving" @click="save">保存</el-button></div>
    </aside>
  </section>
</template>

<script>
import { listEntity, listRelations, saveRelation, deleteRelation } from '../../../api/erp/master'
const emptyForm = () => ({ id: null, sku_id: null, item_id: null, relation_type: 'finished_product', qty: 1, unit_id: null, is_primary: true, is_bundle_item: false, status: 'enabled', remark: '' })
export default {
  name: 'SkuItemRelationList',
  data() {
    return {
      skus: [], items: [], units: [], rows: [], loading: false, saving: false, drawerVisible: true,
      selectedSku: {}, filters: { sku: '', item: '', role: '', status: '' }, form: emptyForm(),
      types: [
        { value: 'finished_product', label: '成品' },
        { value: 'sales_bundle_item', label: '套装/组合销售' },
        { value: 'shipping_accessory', label: '固定随货配件' },
        { value: 'packaging', label: '包装物' },
        { value: 'service_none', label: '无实体服务项' }
      ],
      rules: { sku_id: [{ required: true, message: '请选择 SKU' }], relation_type: [{ required: true, message: '请选择关系角色' }], qty: [{ required: true, message: '请填写转换数量' }] }
    }
  },
  computed: {
    filteredSkus() {
      const skuKw = this.filters.sku.trim().toLowerCase()
      const itemKw = this.filters.item.trim().toLowerCase()
      return this.skus.filter(sku => {
        const skuOk = !skuKw || `${sku.sku_code || ''}${sku.sku_name || ''}`.toLowerCase().includes(skuKw)
        const relations = this.relationsForSku(sku.id)
        const itemOk = !itemKw || relations.some(r => `${r.item?.item_code || ''}${r.item?.item_name || ''}`.toLowerCase().includes(itemKw))
        const roleOk = !this.filters.role || relations.some(r => r.relation_type === this.filters.role)
        const statusOk = !this.filters.status || sku.status === this.filters.status
        return skuOk && itemOk && roleOk && statusOk
      })
    },
    currentRelations() { return this.relationsForSku(this.selectedSku.id) }
  },
  async created() { await this.loadBase(); await this.loadRelations() },
  methods: {
    async loadBase() {
      const [skus, items, units] = await Promise.all([listEntity('skus', { per_page: 100 }), listEntity('items', { per_page: 100 }), listEntity('units', { per_page: 100 })])
      this.skus = skus.data.data || []; this.items = items.data.data || []; this.units = units.data.data || []
      if (this.skus.length) this.selectedSku = this.skus[0]
    },
    async loadRelations() { this.loading = true; try { const { data } = await listRelations({ per_page: 100 }); this.rows = data.data || [] } catch (e) { this.$message.error(e.userMessage || '关系加载失败') } finally { this.loading = false } },
    relationsForSku(id) { return this.rows.filter(r => Number(r.sku_id) === Number(id)) },
    selectSku(row) { this.selectedSku = row; this.form = { ...emptyForm(), sku_id: row.id } },
    reset() { this.filters = { sku: '', item: '', role: '', status: '' } },
    openCreate() { if (!this.selectedSku.id) return this.$message.warning('请先选择 SKU'); this.form = { ...emptyForm(), sku_id: this.selectedSku.id }; this.drawerVisible = true; this.$nextTick(() => this.$refs.form && this.$refs.form.clearValidate()) },
    openEdit(row) { this.form = { ...emptyForm(), ...row, qty: Number(row.qty || 1) }; this.drawerVisible = true; this.$nextTick(() => this.$refs.form && this.$refs.form.clearValidate()) },
    async save() {
      this.$refs.form.validate(async ok => {
        if (!ok) return
        this.saving = true
        try {
          await saveRelation(this.form)
          this.$message.success('关系保存成功')
          await this.loadRelations()
        } catch (e) {
          if (e.response && e.response.status === 409) {
            try {
              await this.$confirm('只有套装、组合销售、固定随货配件，才需要一个 SKU 关联多个 Item。生产用料请在 BOM 中维护，不要在这里维护。确认继续？', '添加第二个 Item', { type: 'warning' })
              this.form.multi_item_confirmed = true
              await saveRelation(this.form)
              this.$message.success('关系保存成功')
              await this.loadRelations()
            } catch (_) {}
          } else this.$message.error(e.userMessage || '关系保存失败')
        } finally { this.saving = false }
      })
    },
    async remove(row) { try { await this.$confirm('确认解除该 SKU 与 Item 的关系？', '删除确认', { type: 'warning' }); await deleteRelation(row.id); await this.loadRelations(); this.$message.success('关系已解除') } catch (e) { if (e !== 'cancel') this.$message.error(e.userMessage || '解除失败') } },
    skuRowClass({ row }) { return row.id === this.selectedSku.id ? 'selected-row' : '' },
    typeText(v) { return (this.types.find(t => t.value === v) || {}).label || v || '-' },
    statusText(v) { return v === 'disabled' ? '停用' : '正常' }
  }
}
</script>

