<template>
  <section class="base-page" :class="{ 'drawer-open': drawerVisible }">
    <div class="base-workspace">
      <div class="base-head">
        <h1>基础档案</h1>
        <div class="base-tabs">
          <button :class="{ active: activeTab === 'units' }" @click="switchTab('units')">单位管理</button>
          <button :class="{ active: activeTab === 'categories' }" @click="switchTab('categories')">分类管理</button>
        </div>
      </div>

      <template v-if="activeTab === 'units'">
        <div class="filter-bar">
          <el-input v-model="unitQuery.keyword" size="small" clearable prefix-icon="el-icon-search" placeholder="单位编码/名称" />
          <el-select v-model="unitQuery.unit_type" size="small" clearable placeholder="单位类型">
            <el-option label="数量" value="quantity" />
            <el-option label="重量" value="weight" />
            <el-option label="长度" value="length" />
            <el-option label="体积" value="volume" />
          </el-select>
          <el-select v-model="unitQuery.status" size="small" clearable placeholder="状态">
            <el-option label="启用" value="enabled" />
            <el-option label="停用" value="disabled" />
          </el-select>
          <span class="spacer" />
          <el-button size="small" @click="resetUnits">重置</el-button>
          <el-button size="small" type="success" @click="loadUnits">查询</el-button>
          <el-button size="small" type="success" icon="el-icon-plus" @click="openUnitCreate">新增单位</el-button>
        </div>

        <div class="panel">
          <el-table :data="filteredUnits" size="mini" border :row-class-name="unitRowClass" @row-click="openUnitDetail">
            <el-table-column prop="unit_code" label="单位编码" min-width="90" />
            <el-table-column prop="unit_name" label="单位名称" min-width="90" />
            <el-table-column label="单位类型" min-width="90"><template slot-scope="{ row }">{{ unitTypeText(row.unit_type) }}</template></el-table-column>
            <el-table-column prop="decimal_places" label="小数位数" width="82" align="center" />
            <el-table-column label="是否基本单位" width="108" align="center"><template slot-scope="{ row }"><el-tag size="mini" :type="row.is_base ? 'success' : 'info'" effect="plain">{{ row.is_base ? '是' : '否' }}</el-tag></template></el-table-column>
            <el-table-column label="使用对象数" width="96" align="right"><template slot-scope="{ row }">{{ usageCount(row) }}</template></el-table-column>
            <el-table-column label="状态" width="82"><template slot-scope="{ row }"><span class="state-dot" :class="row.status">{{ statusText(row.status) }}</span></template></el-table-column>
            <el-table-column label="更新时间" min-width="140"><template slot-scope="{ row }">{{ formatDate(row.updated_at) }}</template></el-table-column>
            <el-table-column label="操作" width="142" fixed="right"><template slot-scope="{ row }"><el-button type="text" size="mini" @click.stop="openUnitEdit(row)">编辑</el-button><el-button type="text" size="mini" class="danger-link" @click.stop="disableUnit(row)">禁用</el-button><el-button type="text" size="mini" @click.stop="openConversionCreate(row)">换算</el-button></template></el-table-column>
          </el-table>
          <div class="pager">共 {{ filteredUnits.length }} 条</div>
        </div>

        <div class="panel conversion-panel">
          <div class="panel-title"><strong>单位换算组</strong><span>维护单位之间的换算比例</span><el-button size="mini" type="success" plain icon="el-icon-plus" @click="openConversionCreate(selectedUnit)">新增换算</el-button></div>
          <el-table :data="conversions" size="mini" border empty-text="暂无换算关系，请新增换算">
            <el-table-column label="换算方向" width="86"><template slot-scope="{ $index }">{{ $index % 2 === 0 ? '正向' : '反向' }}</template></el-table-column>
            <el-table-column label="来源单位" min-width="120"><template slot-scope="{ row }">{{ unitLabel(row.source_unit || row.sourceUnit, row.source_unit_id) }}</template></el-table-column>
            <el-table-column label="目标单位" min-width="120"><template slot-scope="{ row }">{{ unitLabel(row.target_unit || row.targetUnit, row.target_unit_id) }}</template></el-table-column>
            <el-table-column label="换算比例" width="100"><template slot-scope="{ row }">1 : {{ row.ratio }}</template></el-table-column>
            <el-table-column prop="formula" label="换算公式" min-width="150" />
            <el-table-column prop="decimal_places" label="小数位数" width="82" align="center" />
            <el-table-column label="状态" width="82"><template slot-scope="{ row }"><span class="state-dot" :class="row.status">{{ statusText(row.status) }}</span></template></el-table-column>
            <el-table-column label="更新时间" min-width="140"><template slot-scope="{ row }">{{ formatDate(row.updated_at) }}</template></el-table-column>
            <el-table-column label="操作" width="96"><template slot-scope="{ row }"><el-button type="text" size="mini" @click="openConversionEdit(row)">编辑</el-button><el-button type="text" size="mini" class="danger-link" @click="disableConversion(row)">删除</el-button></template></el-table-column>
          </el-table>
        </div>
      </template>

      <template v-else>
        <div class="category-layout">
          <aside class="category-side">
            <button v-for="type in categoryTypes" :key="type.value" :class="{ active: categoryQuery.category_type === type.value }" @click="selectCategoryType(type.value)">
              <b>{{ type.label }}</b>
              <span>{{ categoryCount(type.value) }} 条</span>
            </button>
          </aside>
          <main class="category-main">
            <div class="filter-bar category-filter">
              <el-input v-model="categoryQuery.keyword" size="small" clearable prefix-icon="el-icon-search" placeholder="分类编码/名称" />
              <el-select v-model="categoryQuery.status" size="small" clearable placeholder="状态">
                <el-option label="启用" value="enabled" />
                <el-option label="停用" value="disabled" />
              </el-select>
              <span class="spacer" />
              <el-button size="small" @click="resetCategories">重置</el-button>
              <el-button size="small" type="success" @click="loadCategories">查询</el-button>
              <el-button size="small" type="success" icon="el-icon-plus" @click="openCategoryCreate">新增分类</el-button>
            </div>
            <div class="panel">
              <el-table :data="filteredCategories" size="mini" border :row-class-name="categoryRowClass" @row-click="openCategoryDetail">
                <el-table-column prop="category_code" label="分类编码" min-width="110" />
                <el-table-column prop="category_name" label="分类名称" min-width="140" />
                <el-table-column label="分类类型" width="96"><template slot-scope="{ row }">{{ categoryTypeText(row.category_type) }}</template></el-table-column>
                <el-table-column label="父级分类" min-width="120"><template slot-scope="{ row }">{{ row.parent ? row.parent.category_name : '-' }}</template></el-table-column>
                <el-table-column prop="sort_order" label="排序" width="70" align="center" />
                <el-table-column label="状态" width="82"><template slot-scope="{ row }"><span class="state-dot" :class="row.status">{{ statusText(row.status) }}</span></template></el-table-column>
                <el-table-column label="更新时间" min-width="140"><template slot-scope="{ row }">{{ formatDate(row.updated_at) }}</template></el-table-column>
                <el-table-column label="操作" width="118"><template slot-scope="{ row }"><el-button type="text" size="mini" @click.stop="openCategoryEdit(row)">编辑</el-button><el-button type="text" size="mini" class="danger-link" @click.stop="disableCategory(row)">禁用</el-button></template></el-table-column>
              </el-table>
              <div class="pager">共 {{ filteredCategories.length }} 条</div>
            </div>
          </main>
        </div>
      </template>
    </div>

    <aside v-if="drawerVisible" class="base-drawer">
      <div class="drawer-head"><h2>{{ drawerTitle }}</h2><i class="el-icon-close" @click="drawerVisible=false" /></div>
      <div v-if="drawerMode.endsWith('detail')" class="drawer-body">
        <section class="drawer-card">
          <h3>基础信息</h3>
          <dl v-if="drawerMode === 'unit-detail'">
            <dt>单位编码</dt><dd>{{ selectedUnit.unit_code }}</dd>
            <dt>单位名称</dt><dd>{{ selectedUnit.unit_name }}</dd>
            <dt>单位类型</dt><dd>{{ unitTypeText(selectedUnit.unit_type) }}</dd>
            <dt>小数位数</dt><dd>{{ selectedUnit.decimal_places }}</dd>
            <dt>基本单位</dt><dd>{{ selectedUnit.is_base ? '是' : '否' }}</dd>
            <dt>状态</dt><dd>{{ statusText(selectedUnit.status) }}</dd>
          </dl>
          <dl v-else>
            <dt>分类编码</dt><dd>{{ selectedCategory.category_code }}</dd>
            <dt>分类名称</dt><dd>{{ selectedCategory.category_name }}</dd>
            <dt>分类类型</dt><dd>{{ categoryTypeText(selectedCategory.category_type) }}</dd>
            <dt>父级分类</dt><dd>{{ selectedCategory.parent ? selectedCategory.parent.category_name : '-' }}</dd>
            <dt>排序</dt><dd>{{ selectedCategory.sort_order }}</dd>
            <dt>状态</dt><dd>{{ statusText(selectedCategory.status) }}</dd>
          </dl>
        </section>
        <section class="drawer-card note">
          <h3>规则提示</h3>
          <p v-if="drawerMode === 'unit-detail'">单位编码创建后不可修改；已被引用单位不能删除，只能禁用；同一单位类型只能有一个基本单位。</p>
          <p v-else>分类用于商品、物料、供应商主数据归档。分类编码创建后应保持稳定，避免影响后续业务引用。</p>
        </section>
      </div>
      <el-form v-else-if="drawerMode.startsWith('unit-')" ref="unitForm" :model="unitForm" :rules="unitRules" label-position="top" size="small" class="drawer-body">
        <el-form-item label="单位编码" prop="unit_code"><el-input v-model="unitForm.unit_code" :disabled="drawerMode === 'unit-edit'" /></el-form-item>
        <el-form-item label="单位名称" prop="unit_name"><el-input v-model="unitForm.unit_name" /></el-form-item>
        <el-form-item label="单位类型" prop="unit_type"><el-select v-model="unitForm.unit_type" class="full"><el-option label="数量" value="quantity" /><el-option label="重量" value="weight" /><el-option label="长度" value="length" /><el-option label="体积" value="volume" /></el-select></el-form-item>
        <el-form-item label="小数位数" prop="decimal_places"><el-input-number v-model="unitForm.decimal_places" :min="0" :max="6" controls-position="right" /></el-form-item>
        <el-form-item label="是否基本单位"><el-switch v-model="unitForm.is_base" active-color="#07883f" /></el-form-item>
        <el-form-item label="状态"><el-radio-group v-model="unitForm.status"><el-radio label="enabled">启用</el-radio><el-radio label="disabled">停用</el-radio></el-radio-group></el-form-item>
        <el-form-item label="备注"><el-input v-model="unitForm.remark" type="textarea" :rows="3" /></el-form-item>
      </el-form>
      <el-form v-else-if="drawerMode.startsWith('category-')" ref="categoryForm" :model="categoryForm" :rules="categoryRules" label-position="top" size="small" class="drawer-body">
        <el-form-item label="分类编码" prop="category_code"><el-input v-model="categoryForm.category_code" :disabled="drawerMode === 'category-edit'" /></el-form-item>
        <el-form-item label="分类名称" prop="category_name"><el-input v-model="categoryForm.category_name" /></el-form-item>
        <el-form-item label="分类类型" prop="category_type"><el-select v-model="categoryForm.category_type" class="full"><el-option v-for="type in categoryTypes" :key="type.value" :label="type.label" :value="type.value" /></el-select></el-form-item>
        <el-form-item label="父级分类"><el-select v-model="categoryForm.parent_id" clearable filterable class="full"><el-option v-for="c in parentCategoryOptions" :key="c.id" :label="c.category_name" :value="c.id" /></el-select></el-form-item>
        <el-form-item label="排序"><el-input-number v-model="categoryForm.sort_order" :min="0" controls-position="right" /></el-form-item>
        <el-form-item label="状态"><el-radio-group v-model="categoryForm.status"><el-radio label="enabled">启用</el-radio><el-radio label="disabled">停用</el-radio></el-radio-group></el-form-item>
        <el-form-item label="备注"><el-input v-model="categoryForm.remark" type="textarea" :rows="3" /></el-form-item>
      </el-form>
      <el-form v-else ref="conversionForm" :model="conversionForm" :rules="conversionRules" label-position="top" size="small" class="drawer-body">
        <el-form-item label="来源单位" prop="source_unit_id"><el-select v-model="conversionForm.source_unit_id" filterable class="full"><el-option v-for="u in units" :key="u.id" :label="unitOptionLabel(u)" :value="u.id" /></el-select></el-form-item>
        <el-form-item label="目标单位" prop="target_unit_id"><el-select v-model="conversionForm.target_unit_id" filterable class="full"><el-option v-for="u in units" :key="u.id" :label="unitOptionLabel(u)" :value="u.id" /></el-select></el-form-item>
        <el-form-item label="换算比例" prop="ratio"><el-input-number v-model="conversionForm.ratio" :min="0.000001" :precision="6" controls-position="right" /></el-form-item>
        <el-form-item label="换算公式"><el-input v-model="conversionForm.formula" placeholder="例如：1 kg = 1000 g" /></el-form-item>
        <el-form-item label="小数位数"><el-input-number v-model="conversionForm.decimal_places" :min="0" :max="8" controls-position="right" /></el-form-item>
        <el-form-item label="状态"><el-radio-group v-model="conversionForm.status"><el-radio label="enabled">启用</el-radio><el-radio label="disabled">停用</el-radio></el-radio-group></el-form-item>
      </el-form>
      <div class="drawer-footer">
        <el-button size="small" @click="drawerVisible=false">取消</el-button>
        <el-button v-if="drawerMode.endsWith('detail')" size="small" type="success" @click="drawerMode === 'unit-detail' ? openUnitEdit(selectedUnit) : openCategoryEdit(selectedCategory)">编辑</el-button>
        <el-button v-else size="small" type="success" :loading="saving" @click="saveDrawer">保存</el-button>
      </div>
    </aside>
  </section>
</template>

<script>
import { listEntity, saveEntity, disableEntity, listUnitConversions, saveUnitConversion } from '../../../api/erp/master'

const emptyUnit = () => ({ id: null, unit_code: '', unit_name: '', unit_type: 'quantity', decimal_places: 0, is_base: false, status: 'enabled', remark: '' })
const emptyCategory = () => ({ id: null, category_code: '', category_name: '', parent_id: null, category_type: 'product', sort_order: 0, status: 'enabled', remark: '' })
const emptyConversion = () => ({ id: null, source_unit_id: null, target_unit_id: null, ratio: 1, formula: '', decimal_places: 3, status: 'enabled' })

export default {
  name: 'UnitList',
  data() {
    return {
      activeTab: 'units',
      drawerVisible: false,
      drawerMode: 'unit-detail',
      saving: false,
      units: [],
      conversions: [],
      categories: [],
      selectedUnit: {},
      selectedCategory: {},
      unitForm: emptyUnit(),
      categoryForm: emptyCategory(),
      conversionForm: emptyConversion(),
      unitQuery: { keyword: '', unit_type: '', status: '' },
      categoryQuery: { keyword: '', category_type: 'product', status: '' },
      categoryTypes: [
        { value: 'product', label: '商品分类' },
        { value: 'item', label: '物料分类' },
        { value: 'supplier', label: '供应商分类' }
      ],
      unitRules: {
        unit_code: [{ required: true, message: '请输入单位编码', trigger: 'blur' }],
        unit_name: [{ required: true, message: '请输入单位名称', trigger: 'blur' }],
        unit_type: [{ required: true, message: '请选择单位类型', trigger: 'change' }]
      },
      categoryRules: {
        category_code: [{ required: true, message: '请输入分类编码', trigger: 'blur' }],
        category_name: [{ required: true, message: '请输入分类名称', trigger: 'blur' }],
        category_type: [{ required: true, message: '请选择分类类型', trigger: 'change' }]
      },
      conversionRules: {
        source_unit_id: [{ required: true, message: '请选择来源单位', trigger: 'change' }],
        target_unit_id: [{ required: true, message: '请选择目标单位', trigger: 'change' }],
        ratio: [{ required: true, message: '请输入换算比例', trigger: 'change' }]
      }
    }
  },
  computed: {
    drawerTitle() {
      const titles = {
        'unit-detail': '单位详情', 'unit-create': '新增单位', 'unit-edit': '编辑单位',
        'category-detail': '分类详情', 'category-create': '新增分类', 'category-edit': '编辑分类',
        'conversion-create': '新增换算', 'conversion-edit': '编辑换算'
      }
      return titles[this.drawerMode] || '基础档案'
    },
    filteredUnits() {
      const kw = this.unitQuery.keyword.trim().toLowerCase()
      return this.units.filter(u => (!kw || `${u.unit_code || ''}${u.unit_name || ''}`.toLowerCase().includes(kw)) && (!this.unitQuery.unit_type || u.unit_type === this.unitQuery.unit_type) && (!this.unitQuery.status || u.status === this.unitQuery.status))
    },
    filteredCategories() {
      const kw = this.categoryQuery.keyword.trim().toLowerCase()
      return this.categories.filter(c => c.category_type === this.categoryQuery.category_type && (!kw || `${c.category_code || ''}${c.category_name || ''}`.toLowerCase().includes(kw)) && (!this.categoryQuery.status || c.status === this.categoryQuery.status))
    },
    parentCategoryOptions() {
      return this.categories.filter(c => c.category_type === this.categoryForm.category_type && c.id !== this.categoryForm.id)
    }
  },
  created() {
    this.loadAll()
  },
  methods: {
    async loadAll() { await Promise.all([this.loadUnits(), this.loadCategories(), this.loadConversions()]) },
    async loadUnits() {
      const { data } = await listEntity('units', { per_page: 100 })
      this.units = data.data || []
      if (!this.selectedUnit.id && this.units.length) this.openUnitDetail(this.units[0])
      if (!this.units.length && this.activeTab === 'units') { this.selectedUnit = {}; this.drawerVisible = false }
    },
    async loadCategories() {
      const { data } = await listEntity('categories', { per_page: 100 })
      this.categories = data.data || []
      if (this.activeTab === 'categories' && !this.selectedCategory.id && this.filteredCategories.length) this.openCategoryDetail(this.filteredCategories[0])
    },
    async loadConversions() {
      const { data } = await listUnitConversions()
      this.conversions = Array.isArray(data) ? data : []
    },
    switchTab(tab) {
      this.activeTab = tab
      if (tab === 'units') {
        if (this.selectedUnit.id) this.openUnitDetail(this.selectedUnit)
        else if (this.units.length) this.openUnitDetail(this.units[0])
      } else {
        if (this.filteredCategories.length) this.openCategoryDetail(this.filteredCategories[0])
        else { this.selectedCategory = {}; this.drawerVisible = false }
      }
    },
    resetUnits() { this.unitQuery = { keyword: '', unit_type: '', status: '' } },
    resetCategories() { this.categoryQuery.keyword = ''; this.categoryQuery.status = '' },
    selectCategoryType(type) { this.categoryQuery.category_type = type; this.selectedCategory = {}; this.filteredCategories.length ? this.openCategoryDetail(this.filteredCategories[0]) : this.drawerVisible = false },
    openUnitDetail(row) { this.selectedUnit = { ...row }; this.drawerMode = 'unit-detail'; this.drawerVisible = true },
    openUnitCreate() { const unit = emptyUnit(); unit.is_base = !this.hasBaseUnit(unit.unit_type); this.unitForm = unit; this.drawerMode = 'unit-create'; this.drawerVisible = true },
    openUnitEdit(row) { this.unitForm = { ...emptyUnit(), ...row, is_base: !!row.is_base }; this.drawerMode = 'unit-edit'; this.drawerVisible = true },
    openCategoryDetail(row) { this.selectedCategory = { ...row }; this.drawerMode = 'category-detail'; this.drawerVisible = true },
    openCategoryCreate() { this.categoryForm = { ...emptyCategory(), category_type: this.categoryQuery.category_type }; this.drawerMode = 'category-create'; this.drawerVisible = true },
    openCategoryEdit(row) { this.categoryForm = { ...emptyCategory(), ...row }; this.drawerMode = 'category-edit'; this.drawerVisible = true },
    openConversionCreate(row) { this.conversionForm = { ...emptyConversion(), source_unit_id: row && row.id ? row.id : this.selectedUnit.id }; this.drawerMode = 'conversion-create'; this.drawerVisible = true },
    openConversionEdit(row) { this.conversionForm = { ...emptyConversion(), ...row, ratio: Number(row.ratio || 1), decimal_places: Number(row.decimal_places || 0) }; this.drawerMode = 'conversion-edit'; this.drawerVisible = true },
    saveDrawer() {
      if (this.drawerMode.startsWith('unit-')) return this.saveUnit()
      if (this.drawerMode.startsWith('category-')) return this.saveCategory()
      return this.saveConversion()
    },
    saveUnit() {
      this.$refs.unitForm.validate(async ok => {
        if (!ok) return
        if (!this.unitForm.is_base && !this.hasBaseUnit(this.unitForm.unit_type, this.unitForm.id)) {
          try { await this.$confirm('当前单位类型还没有基本单位，是否仍保存为非基本单位？', '基本单位确认', { type: 'warning' }) } catch (e) { return }
        }
        this.saving = true
        try { await saveEntity('units', this.unitForm); this.$message.success('单位保存成功'); await this.loadUnits(); this.openUnitDetail(this.units.find(u => u.unit_code === this.unitForm.unit_code) || this.selectedUnit) } catch (e) { this.$message.error(e.userMessage || '单位保存失败') } finally { this.saving = false }
      })
    },
    hasBaseUnit(type, exceptId = null) { return this.units.some(u => u.unit_type === type && !!u.is_base && Number(u.id) !== Number(exceptId)) },
    saveCategory() {
      this.$refs.categoryForm.validate(async ok => {
        if (!ok) return
        this.saving = true
        try { await saveEntity('categories', this.categoryForm); this.$message.success('分类保存成功'); await this.loadCategories(); this.openCategoryDetail(this.categories.find(c => c.category_code === this.categoryForm.category_code) || this.selectedCategory) } catch (e) { this.$message.error(e.userMessage || '分类保存失败') } finally { this.saving = false }
      })
    },
    async saveConversion() {
      this.$refs.conversionForm.validate(async ok => {
        if (!ok) return
        if (this.conversionForm.source_unit_id === this.conversionForm.target_unit_id) return this.$message.warning('来源单位和目标单位不能相同')
        try { await this.$confirm('换算关系变更可能影响已引用该单位的主数据，确认保存？', '保存前风险提示', { type: 'warning' }) } catch (_) { return }
        this.saving = true
        try { await saveUnitConversion(this.conversionForm); this.$message.success('换算保存成功'); await this.loadConversions(); this.openUnitDetail(this.selectedUnit) } catch (e) { this.$message.error(e.userMessage || '换算保存失败') } finally { this.saving = false }
      })
    },
    async disableUnit(row) { try { await this.$confirm('已被引用单位不能删除，只能禁用。确认禁用？', '禁用单位', { type: 'warning' }); await disableEntity('units', row.id); await this.loadUnits() } catch (e) { if (e !== 'cancel') this.$message.error(e.userMessage || '禁用失败') } },
    async disableCategory(row) { try { await this.$confirm('确认禁用该分类？', '禁用分类', { type: 'warning' }); await disableEntity('categories', row.id); await this.loadCategories() } catch (e) { if (e !== 'cancel') this.$message.error(e.userMessage || '禁用失败') } },
    async disableConversion(row) { try { await this.$confirm('确认删除该换算？当前将按停用处理。', '删除换算', { type: 'warning' }); await saveUnitConversion({ ...row, status: 'disabled' }); await this.loadConversions() } catch (e) { if (e !== 'cancel') this.$message.error(e.userMessage || '操作失败') } },
    unitRowClass({ row }) { return row.id === this.selectedUnit.id ? 'selected-row' : '' },
    categoryRowClass({ row }) { return row.id === this.selectedCategory.id ? 'selected-row' : '' },
    unitTypeText(v) { return ({ quantity: '数量', weight: '重量', length: '长度', volume: '体积' })[v] || v || '-' },
    categoryTypeText(v) { return (this.categoryTypes.find(t => t.value === v) || {}).label || v || '-' },
    categoryCount(type) { return this.categories.filter(c => c.category_type === type).length },
    statusText(v) { return v === 'disabled' ? '停用' : '启用' },
    usageCount(row) { return Number(row.usage_count || row.usage_objects_count || row.items_count || row.references_count || 0) },
    formatDate(v) { return v ? String(v).replace('T', ' ').slice(0, 16) : '-' },
    unitOptionLabel(u) { return `${u.unit_code} ${u.unit_name}（${this.unitTypeText(u.unit_type)}）` },
    unitLabel(unit, id) { const found = unit || this.units.find(u => u.id === id); return found ? `${found.unit_code || ''} ${found.unit_name || ''}`.trim() : '-' }
  }
}
</script>

