<template>
  <section class="sales-list-page">
    <div class="sales-main">
      <div class="sales-heading">
        <div>
          <div class="sub-breadcrumb">销售管理 / 销售订单</div>
          <h1>销售订单</h1>
          <p>集中管理销售订单全生命周期，查看订单状态、履约进度、异常与风险，支持订单变更、打印防错。</p>
        </div>
        <div class="heading-actions">
          <el-button v-if="$can('sales.order.create')" size="small" type="success" icon="el-icon-plus" @click="$router.push('/sales/orders/create')">新增订单</el-button>
          <el-button size="small" icon="el-icon-download">导出</el-button>
          <el-button size="small" icon="el-icon-printer">打印</el-button>
        </div>
      </div>

      <div class="metric-grid">
        <div v-for="card in metrics" :key="card.label" class="metric-card">
          <span :class="['metric-icon', card.type]"><i :class="card.icon" /></span>
          <p>{{ card.label }}</p>
          <strong>{{ card.value }}</strong>
        </div>
      </div>

      <div class="search-panel">
        <el-input v-model="query.keyword" clearable size="small" prefix-icon="el-icon-search" placeholder="搜索订单号、原始订单号、客户、Product、SKU" @keyup.enter.native="load" />
        <el-select v-model="query.order_status" clearable size="small" placeholder="订单状态">
          <el-option label="草稿" value="draft" />
          <el-option label="已确认" value="confirmed" />
          <el-option label="已关闭" value="closed" />
          <el-option label="已取消" value="cancelled" />
        </el-select>
        <el-select v-model="query.fulfillment_status" clearable size="small" placeholder="履约状态">
          <el-option label="全部库存履约" value="all_inventory" />
          <el-option label="部分库存部分生产" value="partial_inventory_partial_production" />
          <el-option label="全部生产" value="all_production" />
          <el-option label="服务/无需发货" value="non_physical_only" />
        </el-select>
        <el-select v-model="query.production_confirm_status" clearable size="small" placeholder="生产确认">
          <el-option label="无需确认" value="not_required" />
          <el-option label="待确认" value="pending" />
          <el-option label="已确认" value="confirmed" />
        </el-select>
        <el-button size="small" type="success" @click="reload">查询</el-button>
        <el-button size="small" @click="reset">重置</el-button>
      </div>

      <div class="status-tabs">
        <button v-for="tab in tabs" :key="tab.value" :class="{ active: activeTab === tab.value }" @click="switchTab(tab.value)">
          {{ tab.label }} <small>{{ tab.count }}</small>
        </button>
      </div>

      <div class="list-layout">
        <div class="table-card">
          <el-table
            v-loading="loading"
            :data="rows"
            border
            size="mini"
            highlight-current-row
            @current-change="selectOrder"
          >
            <el-table-column type="selection" width="38" />
            <el-table-column prop="sales_order_no" label="订单号" width="130" fixed />
            <el-table-column prop="origin_order_no" label="原始订单号" width="110" show-overflow-tooltip />
            <el-table-column label="客户名称" min-width="150" show-overflow-tooltip>
              <template slot-scope="{row}">
                <strong>{{ row.customer_name || '-' }}</strong>
                <small class="muted">{{ row.customer_phone || row.contact_phone || '-' }}</small>
              </template>
            </el-table-column>
            <el-table-column prop="created_by" label="销售" width="70" />
            <el-table-column label="订单日期" width="92">
              <template slot-scope="{row}">{{ dateOnly(row.order_time) }}</template>
            </el-table-column>
            <el-table-column label="要求交期" width="92">
              <template slot-scope="{row}">{{ dateOnly(row.required_delivery_date) }}</template>
            </el-table-column>
            <el-table-column label="金额" width="100" align="right">
              <template slot-scope="{row}">¥{{ money(row.total_amount) }}</template>
            </el-table-column>
            <el-table-column label="订单状态" width="88">
              <template slot-scope="{row}"><el-tag size="mini" :type="statusTag(row.order_status)">{{ statusText(row.order_status) }}</el-tag></template>
            </el-table-column>
            <el-table-column label="履约状态" width="104">
              <template slot-scope="{row}"><el-tag size="mini" :type="statusTag(row.fulfillment_status)">{{ statusText(row.fulfillment_status) }}</el-tag></template>
            </el-table-column>
            <el-table-column label="生产确认" width="88">
              <template slot-scope="{row}"><el-tag size="mini" :type="statusTag(row.production_confirm_status)">{{ statusText(row.production_confirm_status) }}</el-tag></template>
            </el-table-column>
            <el-table-column label="标记" width="96">
              <template slot-scope="{row}">
                <el-tag v-if="row.is_urgent" size="mini" type="danger">加急</el-tag>
                <el-tag v-if="row.is_delay" size="mini" type="warning">延期</el-tag>
                <el-tag v-if="row.is_customized" size="mini">定制</el-tag>
                <span v-if="!row.is_urgent && !row.is_delay && !row.is_customized" class="muted">-</span>
              </template>
            </el-table-column>
            <el-table-column label="操作" width="140" fixed="right">
              <template slot-scope="{row}">
                <el-button type="text" size="mini" @click.stop="$router.push(`/sales/orders/${row.id}/detail`)">查看详情</el-button>
                <el-button v-if="$can('sales.order.edit') && row.order_status !== 'cancelled' && row.shipment_status !== 'shipped'" type="text" size="mini" @click.stop="$router.push(`/sales/orders/${row.id}/edit`)">编辑</el-button>
                <el-button v-if="row.order_status === 'draft' && $can('sales.order.confirm')" type="text" size="mini" @click.stop="confirmOrder(row)">确认</el-button>
                <el-dropdown v-if="moreActions(row).length" trigger="click" @command="cmd => handleCommand(cmd, row)">
                  <span class="more-link">更多<i class="el-icon-arrow-down" /></span>
                  <el-dropdown-menu slot="dropdown">
                    <el-dropdown-item v-for="item in moreActions(row)" :key="item.command" :command="item.command">{{ item.label }}</el-dropdown-item>
                  </el-dropdown-menu>
                </el-dropdown>
              </template>
            </el-table-column>
          </el-table>
          <el-pagination
            background
            layout="total, sizes, prev, pager, next, jumper"
            :current-page.sync="query.page"
            :page-size.sync="query.per_page"
            :page-sizes="[10, 20, 50, 100]"
            :total="total"
            @current-change="load"
            @size-change="reload"
          />
        </div>

        <aside class="order-side">
          <div class="side-head">
            <strong>订单阻塞信息（关联订单）</strong>
            <i class="el-icon-close" @click="selected = null" />
          </div>
          <div v-if="selected" class="side-body">
            <h3>{{ selected.sales_order_no }}</h3>
            <el-tag size="mini" :type="statusTag(selected.fulfillment_status)">{{ statusText(selected.fulfillment_status) }}</el-tag>
            <dl>
              <dt>客户</dt><dd>{{ selected.customer_name || '-' }}</dd>
              <dt>金额</dt><dd>¥{{ money(selected.total_amount) }}</dd>
              <dt>订单行</dt><dd>{{ (selected.lines || []).length }} 行</dd>
              <dt>生产确认</dt><dd>{{ statusText(selected.production_confirm_status) }}</dd>
            </dl>
            <div class="side-actions">
              <el-button size="small" plain @click="$router.push(`/sales/orders/${selected.id}/detail`)">查看详情</el-button>
              <el-button v-if="$can('sales.order.edit') && selected.order_status !== 'cancelled' && selected.shipment_status !== 'shipped'" size="small" plain @click="$router.push(`/sales/orders/${selected.id}/edit`)">编辑订单</el-button>
              <el-button v-if="selected.production_confirm_status === 'pending'" size="small" type="success" @click="$router.push(`/sales/orders/${selected.id}/production-confirmation`)">去确认生产</el-button>
            </div>
          </div>
          <div v-else class="side-empty">
            <i class="el-icon-document-checked" />
            <strong>请选择订单查看阻塞信息</strong>
            <p>从左侧列表选择订单，查看当前阻塞原因与建议处理入口。</p>
          </div>
          <div class="quick-entry">
            <h4>快速入口</h4>
            <button @click="$router.push('/sales/production-confirmation')">订单生产确认</button>
            <button disabled>订单履约工作台（后续）</button>
            <button disabled>订单变更（后续）</button>
          </div>
          <div class="warning-box">
            <b><i class="el-icon-warning" /> 重要提示</b>
            <p>订单确认后先生成库存/生产履约拆分，不直接生成销售订单工单。</p>
            <p>售后、退货单为后续独立阶段，不进入本批订单主流程。</p>
          </div>
        </aside>
      </div>
    </div>
  </section>
</template>

<script>
import { cancelSalesOrder, confirmSalesOrder, listSalesOrders } from '@/api/erp/sales'
import { statusTag, statusText } from '@/utils/erpStatus'

export default {
  data: () => ({
    loading: false,
    rows: [],
    total: 0,
    selected: null,
    activeTab: '',
    query: { keyword: '', order_status: '', fulfillment_status: '', production_confirm_status: '', page: 1, per_page: 20 }
  }),
  computed: {
    metrics() {
      const all = this.total
      const draft = this.rows.filter(r => r.order_status === 'draft').length
      const pending = this.rows.filter(r => r.production_confirm_status === 'pending').length
      const inventory = this.rows.filter(r => r.fulfillment_status === 'all_inventory').length
      const mixed = this.rows.filter(r => r.fulfillment_status === 'partial_inventory_partial_production').length
      const production = this.rows.filter(r => r.fulfillment_status === 'all_production').length
      const exception = this.rows.filter(r => r.order_status === 'cancelled').length
      return [
        { label: '全部订单', value: all, icon: 'el-icon-s-order', type: 'green' },
        { label: '待提交确认', value: draft, icon: 'el-icon-edit-outline', type: 'orange' },
        { label: '待生产确认', value: pending, icon: 'el-icon-cpu', type: 'blue' },
        { label: '库存履约', value: inventory, icon: 'el-icon-box', type: 'purple' },
        { label: '部分生产', value: mixed, icon: 'el-icon-s-operation', type: 'cyan' },
        { label: '全部生产', value: production, icon: 'el-icon-set-up', type: 'red' },
        { label: '异常订单', value: exception, icon: 'el-icon-warning-outline', type: 'red' }
      ]
    },
    tabs() {
      return [
        { label: '全部', value: '', count: this.total },
        { label: '待提交确认', value: 'draft', count: this.rows.filter(r => r.order_status === 'draft').length },
        { label: '待生产确认', value: 'pending-production', count: this.rows.filter(r => r.production_confirm_status === 'pending').length },
        { label: '全部库存履约', value: 'all_inventory', count: this.rows.filter(r => r.fulfillment_status === 'all_inventory').length },
        { label: '部分库存部分生产', value: 'partial_inventory_partial_production', count: this.rows.filter(r => r.fulfillment_status === 'partial_inventory_partial_production').length },
        { label: '全部生产', value: 'all_production', count: this.rows.filter(r => r.fulfillment_status === 'all_production').length }
      ]
    }
  },
  created() {
    this.load()
  },
  methods: {
    async load() {
      this.loading = true
      try {
        const { data } = await listSalesOrders(this.query)
        this.rows = data.data || []
        this.total = data.total || 0
        if (!this.selected && this.rows.length) this.selected = this.rows[0]
      } finally {
        this.loading = false
      }
    },
    reload() {
      this.query.page = 1
      this.load()
    },
    reset() {
      this.activeTab = ''
      this.query = { keyword: '', order_status: '', fulfillment_status: '', production_confirm_status: '', page: 1, per_page: 20 }
      this.load()
    },
    switchTab(tab) {
      this.activeTab = tab
      this.query.order_status = tab === 'draft' ? 'draft' : ''
      this.query.production_confirm_status = tab === 'pending-production' ? 'pending' : ''
      this.query.fulfillment_status = ['all_inventory', 'partial_inventory_partial_production', 'all_production'].includes(tab) ? tab : ''
      this.reload()
    },
    selectOrder(row) {
      this.selected = row
    },
    async confirmOrder(row) {
      await this.$confirm('确认后将生成库存/生产履约拆分，但不会生成正式工单。继续吗？', '确认销售订单', { type: 'warning' })
      await confirmSalesOrder(row.id)
      this.$message.success('订单已确认')
      this.load()
    },
    moreActions(row) {
      const actions = []
      if (this.$can('sales.order.edit') && row.order_status !== 'cancelled' && row.shipment_status !== 'shipped') actions.push({ command: 'edit', label: '编辑订单' })
      if (row.production_confirm_status === 'pending') actions.push({ command: 'production', label: '订单生产确认' })
      if (row.shipment_status === 'not_shipped' && row.order_status !== 'cancelled' && this.$can('sales.order.cancel')) actions.push({ command: 'cancel', label: '取消订单' })
      if (row.order_status === 'confirmed') actions.push({ command: 'logs', label: '日志与版本' })
      return actions
    },
    async handleCommand(cmd, row) {
      if (cmd === 'edit') this.$router.push(`/sales/orders/${row.id}/edit`)
      if (cmd === 'production') this.$router.push(`/sales/orders/${row.id}/production-confirmation`)
      if (cmd === 'logs') this.$router.push(`/sales/orders/${row.id}/detail?tab=logs`)
      if (cmd === 'cancel') {
        await this.$confirm('取消只影响未履约部分；已发货后必须走售后/退货。确认取消？', '取消订单', { type: 'warning' })
        const prompt = await this.$prompt('请输入取消原因，取消后会释放未使用的库存占用。', '填写取消原因', {
          inputPattern: /\S+/,
          inputErrorMessage: '取消原因不能为空',
          inputType: 'textarea'
        })
        await cancelSalesOrder(row.id, { reason: prompt.value })
        this.$message.success('订单已取消')
        this.load()
      }
    },
    money(value) {
      return Number(value || 0).toLocaleString('zh-CN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })
    },
    statusText,
    statusTag,
    dateOnly(v) {
      return v ? String(v).slice(0, 10) : '-'
    }
  }
}
</script>

